import pandas as pd
from sklearn.preprocessing import LabelEncoder

def task_func(data):
    if isinstance(data, (str, bytes)):
        raise TypeError("data must be an iterable of categorical values, not a string scalar.")

    try:
        values = list(data)
    except TypeError as exc:
        raise TypeError("data must be an iterable of categorical values.") from exc

    if not values:
        return pd.DataFrame(columns=["Category", "Encoded"])

    encoder = LabelEncoder()
    encoded = encoder.fit_transform(values)

    return pd.DataFrame({
        "Category": values,
        "Encoded": encoded,
    })
